package com.fooddelivery.payment.entity;import javax.persistence.*;import java.time.*;@Entity public class Payment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private Long orderId;private double amount;private String status;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public Long getOrderId(){return orderId;}public void setOrderId(Long v){orderId=v;}public double getAmount(){return amount;}public void setAmount(double v){amount=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
